       (92974, 329, 'nl', 'Roter Panda',
        'Der Rote Panda ist ein kleiner, kletterfreudiger Bambusliebhaber mit flauschigem Schwanz. Er lebt in den Bergwäldern Asiens und ist vor allem in Bäumen unterwegs. In deinem Zoo turnt er geschickt auf Ästen herum und schläft eingerollt wie ein kuscheliges Fellknäuel.'),
       (92975, 329, 'fr', 'Roter Panda',
        'Der Rote Panda ist ein kleiner, kletterfreudiger Bambusliebhaber mit flauschigem Schwanz. Er lebt in den Bergwäldern Asiens und ist vor allem in Bäumen unterwegs. In deinem Zoo turnt er geschickt auf Ästen herum und schläft eingerollt wie ein kuscheliges Fellknäuel.'),
       (92976, 329, 'es', 'Roter Panda',
