       (93782, 30175, 'nl', 'Eurasian Golden Oriole',
        'The Eurasian Golden Oriole is a striking yellow-and-black bird with vibrant golden-yellow plumage, black wings, and a black eye stripe, resembling a tropical vision in Europe\\\'s temperate forests. Males are brighter; females greenish-yellow. They are known for its fluty, bubbling song and agile, undulating flight. \\n\\nEurasian Golden Oriole\\\'s diet mainly consists of insects like caterpillars, plus fruits, berries, and nectar.\\n\\n'),
       (93783, 30175, 'fr', 'Eurasian Golden Oriole',
