       (93788, 30177, 'nl', 'European Mouflon',
        'The European Mouflon is a small, wild sheep subspecies native to the Mediterranean islands of Sardinia and Corsica. It is considered the ancestor of domestic , known for its agile, mountain-dwelling lifestyle. They have reddish-brown coats with white underbellies, dark leg stripes, and large, curved horns in rams (up to 80 cm (32 inches) long) for defense and display.\\n\\nThe European Mouflon is a herbivorous grazer and browser, adapted to nutrient-poor Mediterranean vegetation. \\n\\n'),
       (93789, 30177, 'fr', 'European Mouflon',
        'The European Mouflon is a small, wild sheep subspecies native to the Mediterranean islands of Sardinia and Corsica. It is considered the ancestor of domestic , known for its agile, mountain-dwelling lifestyle. They have reddish-brown coats with white underbellies, dark leg stripes, and large, curved horns in rams (up to 80 cm (32 inches) long) for defense and display.\\n\\nThe European Mouflon is a herbivorous grazer and browser, adapted to nutrient-poor Mediterranean vegetation. \\n\\n'),
       (93790, 30177, 'es', 'European Mouflon',
