       (93827, 30191, 'nl', 'Grizzly Bear',
        'The Grizzly Bear is a population or subspecies of the Brown Bear that is found in North America. Although variable in color from blond to nearly black, Grizzly Bear fur is typically brown with darker legs and commonly white or blond-tipped fur on the flank and back. Grizzlies are characterized by their distinctive hump on the shoulders, which is made up of muscle used for digging and foraging. \\n\\nGrizzly Bears are omnivorous, feeding on a varied diet that includes berries, fish, small mammals, and carrion.\\n\\n'),
       (93828, 30191, 'fr', 'Grizzly Bear',
        'The Grizzly Bear is a population or subspecies of the Brown Bear that is found in North America. Although variable in color from blond to nearly black, Grizzly Bear fur is typically brown with darker legs and commonly white or blond-tipped fur on the flank and back. Grizzlies are characterized by their distinctive hump on the shoulders, which is made up of muscle used for digging and foraging. \\n\\nGrizzly Bears are omnivorous, feeding on a varied diet that includes berries, fish, small mammals, and carrion.\\n\\n'),
