       (93905, 30217, 'nl', 'Matschie\\\'s Tree Kangaroo',
        'The Matschie’s Tree Kangaroo has thick, reddish mahogany fur on its back and a dark stripe down its spine. Its limbs, feet and ear tips are yellow, and its face is white or cream-colored. As arboreal animal with a body and head length of 20 to 32 inches (51–81 cm), it spends most of its time in trees. When hopping and walking, the animal moves its limbs alternately, as opposed to other kangaroos. \\n\\nMatschie\\\'s Tree Kangaroos primarily eat tree leaves. They also consume flowers, grass shoots, ferns, moss, and bark.\\n\\nUnder the IUCN classification, Matschie\\\'s Tree Kangaroo is an endangered species.\\n\\n'),
       (93906, 30217, 'fr', 'Matschie\\\'s Tree Kangaroo',
        'The Matschie’s Tree Kangaroo has thick, reddish mahogany fur on its back and a dark stripe down its spine. Its limbs, feet and ear tips are yellow, and its face is white or cream-colored. As arboreal animal with a body and head length of 20 to 32 inches (51–81 cm), it spends most of its time in trees. When hopping and walking, the animal moves its limbs alternately, as opposed to other kangaroos. \\n\\nMatschie\\\'s Tree Kangaroos primarily eat tree leaves. They also consume flowers, grass shoots, ferns, moss, and bark.\\n\\nUnder the IUCN classification, Matschie\\\'s Tree Kangaroo is an endangered species.\\n\\n'),
       (93907, 30217, 'es', 'Matschie\\\'s Tree Kangaroo',
